import { posix } from "node:path";
import type { ContractTree, ScannedFolder } from "./scan";

/** A generated file: a path relative to the project, with `/` separators, and its content. */
export interface GeneratedFile {
  readonly path: string;
  readonly content: string;
}

export interface EmitOptions {
  /** Scan root, relative to the project: `app/api`. */
  readonly root: string;
  /** Output folder, relative to the project: `.laratype`. */
  readonly outDir: string;
}

const BANNER = "// Generated by `sauf types:generate`. Do not edit.\n";

/**
 * Joins generated lines, each ending with "\n". Every line stays its own string literal: a literal that holds
 * "\nimport" or "\nexport" would make the bundled CJS dist look like ESM to publint (check:pkg).
 */
export const lines = (parts: readonly string[]) => parts.map((l) => `${l}\n`).join("");

/** A single-quoted string literal (backslashes, quotes and newlines escaped). Shared by every generated file. */
export const quote = (s: string) => `'${s.replace(/\\/g, "\\\\").replace(/'/g, "\\'").replace(/\n/g, "\\n")}'`;

/** Relative module specifier without the `.ts` extension: `../_scope`, `./_scope`. */
const specifier = (fromDir: string, toFile: string) => {
  const rel = posix.relative(fromDir, toFile.replace(/\.ts$/, ""));
  return rel.startsWith(".") ? rel : `./${rel}`;
};

const prefixType = (path: string, scopes: readonly string[], fromDir: string) =>
  `ContractPrefix<${quote(path)}, [${scopes.map((s) => `typeof import(${quote(specifier(fromDir, s))}).default`).join(", ")}]>`;

/**
 * `<outDir>/types/<root>/<dir>/$types.d.ts`, overlaid on `<root>/<dir>/` through tsconfig `rootDirs`, so the
 * `typeof import('./_scope')` specifiers resolve to the source scopes.
 * `Prefix` is for the folder's contracts (its own scope included); `ScopePrefix` is for its `_scope.ts` (outer scopes only).
 */
export function emitTypesFile(folder: ScannedFolder, options: EmitOptions): GeneratedFile {
  const dir = posix.join(options.root, folder.dir);
  const scopes = folder.scope ? [...folder.outerScopes, folder.scope] : folder.outerScopes;
  const abs = (s: string) => posix.join(options.root, s);
  const content =
    BANNER +
    lines([
      "import type { ContractPrefix } from '@laratype/contract'",
      "",
      `export type Prefix = ${prefixType(folder.path, scopes.map(abs), dir)}`,
      `export type ScopePrefix = ${prefixType(folder.path, folder.outerScopes.map(abs), dir)}`,
    ]);
  return { path: posix.join(options.outDir, "types", dir, "$types.d.ts"), content };
}

/** `<outDir>/api/index.gen.ts`: the aggregated `appApi`, imported as `$api`. */
export function emitApiIndex(tree: ContractTree, options: EmitOptions): GeneratedFile {
  const outDir = posix.join(options.outDir, "api");
  // Each scope file's import id, and its folder (`""` for the root): the `{ scope, dir }` items of a `defineApi` entry
  const scopeIds = new Map<string, string>();
  const scopeDirs = new Map<string, string>();
  for (const folder of tree.folders) {
    if (!folder.scope) continue;
    scopeIds.set(folder.scope, `s${scopeIds.size}`);
    scopeDirs.set(folder.scope, folder.dir);
  }
  const imports = [
    ...[...scopeIds].map(([file, id]) => `import ${id} from ${quote(specifier(outDir, posix.join(options.root, file)))}`),
    ...tree.contracts.map((c, i) => `import c${i} from ${quote(specifier(outDir, posix.join(options.root, c.file)))}`),
  ];
  const entries = tree.contracts.map(
    (c, i) =>
      `  ${quote(c.name)}: { contract: c${i}, path: ${quote(c.path)}, scopes: [${c.scopes.map((s) => `{ scope: ${scopeIds.get(s)}, dir: ${quote(scopeDirs.get(s)!)} }`).join(", ")}] },`,
  );
  const content =
    BANNER +
    lines([
      `// The contract folder tree of ${options.root}. Import it as \`$api\`.`,
      "import { defineApi } from '@laratype/contract'",
      ...imports,
      "",
      ...(entries.length ? ["export const appApi = defineApi({", ...entries, "})"] : ["export const appApi = defineApi({})"]),
      "export type AppApi = typeof appApi",
    ]);
  return { path: posix.join(outDir, "index.gen.ts"), content };
}

/** Every `$types.d.ts` plus `index.gen.ts`. */
export const emitTree = (tree: ContractTree, options: EmitOptions): GeneratedFile[] => [
  ...tree.folders.map((f) => emitTypesFile(f, options)),
  emitApiIndex(tree, options),
];
